1	//! [`BashTool`] — a cwd-pinned shell. **NOT a security sandbox** (see the
2	//! crate-level docs): a spawned command can read/write anything this process
3	//! can. Gate it with a `PermissionPolicy` or `DenyRule::tool("Bash")`.
4	
5	use std::marker::PhantomData;
6	use std::process::Stdio;
7	use std::time::Duration;
8	
9	use async_trait::async_trait;
10	use paigasus_helikon_core::{Tool, ToolContext, ToolEffect, ToolError, ToolOutput};
11	use serde::Deserialize;
12	use serde_json::Value;
13	use tokio::io::AsyncReadExt;
14	
15	use crate::sandbox::Sandbox;
16	
17	const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);
18	const DEFAULT_MAX_OUTPUT: usize = 1 << 20; // 1 MiB
19	
20	/// Grace period for reaping a killed process and for draining its pipes after
21	/// the main timeout fires (or after a successful exit when a backgrounded
22	/// process still holds a pipe open).
23	const GRACE: Duration = Duration::from_secs(5);
24	
25	/// Arguments for [`BashTool`].
26	#[derive(Debug, Deserialize, schemars::JsonSchema)]
27	struct BashArgs {
28	    /// The shell command to run (`sh -c <command>` on unix, `cmd /C` on Windows).
29	    command: String,
30	}
31	
32	/// Builder for [`BashTool`].
33	pub struct BashToolBuilder {
34	    sandbox: Sandbox,
35	    timeout: Duration,
36	    env_allowlist: Vec<String>,
37	    max_output_bytes: usize,
38	    deny_commands: Vec<String>,
39	    allow_commands: Option<Vec<String>>,
40	}
41	
42	impl BashToolBuilder {
43	    /// Maximum wall-clock duration before the command's process group (unix) or
44	    /// the child process (other platforms) is killed.
45	    pub fn timeout(mut self, timeout: Duration) -> Self {
46	        self.timeout = timeout;
47	        self
48	    }
49	
50	    /// Environment variable names to pass through (the rest are dropped). This
51	    /// REPLACES the default `["PATH", "HOME"]` allowlist; include `"PATH"`
52	    /// explicitly if the command needs it.
53	    pub fn env_allowlist<I, S>(mut self, names: I) -> Self
54	    where
55	        I: IntoIterator<Item = S>,
56	        S: Into<String>,
57	    {
58	        self.env_allowlist = names.into_iter().map(Into::into).collect();
59	        self
60	    }
61	
62	    /// Truncate captured stdout/stderr to this many bytes each.
63	    pub fn max_output_bytes(mut self, n: usize) -> Self {
64	        self.max_output_bytes = n;
65	        self
66	    }
67	
68	    /// Refuse any command whose first whitespace-delimited token matches one of
69	    /// these names.
70	    pub fn deny_commands<I, S>(mut self, names: I) -> Self
71	    where
72	        I: IntoIterator<Item = S>,
73	        S: Into<String>,
74	    {
75	        self.deny_commands = names.into_iter().map(Into::into).collect();
76	        self
77	    }
78	
79	    /// If set, allow ONLY commands whose first token is in this list.
80	    pub fn allow_commands<I, S>(mut self, names: I) -> Self
81	    where
82	        I: IntoIterator<Item = S>,
83	        S: Into<String>,
84	    {
85	        self.allow_commands = Some(names.into_iter().map(Into::into).collect());
86	        self
87	    }
88	
89	    /// Finish building.
90	    pub fn build<Ctx>(self) -> BashTool<Ctx> {
91	        BashTool {
92	            sandbox: self.sandbox,
93	            timeout: self.timeout,
94	            env_allowlist: self.env_allowlist,
95	            max_output_bytes: self.max_output_bytes,
96	            deny_commands: self.deny_commands,
97	            allow_commands: self.allow_commands,
98	            schema: serde_json::to_value(schemars::schema_for!(BashArgs))
99	                .expect("BashArgs schema serializes"),
100	            _ctx: PhantomData,
101	        }
102	    }
103	}
104	
105	/// A cwd-pinned shell tool. See the crate-level security note: this is **not**
106	/// a security boundary.
107	pub struct BashTool<Ctx = ()> {
108	    sandbox: Sandbox,
109	    timeout: Duration,
110	    env_allowlist: Vec<String>,
111	    max_output_bytes: usize,
112	    deny_commands: Vec<String>,
113	    allow_commands: Option<Vec<String>>,
114	    schema: Value,
115	    _ctx: PhantomData<fn() -> Ctx>,
116	}
117	
118	impl BashTool<()> {
119	    /// Start building a `BashTool` over `sandbox` (cwd = `sandbox.root()`),
120	    /// with a 30s timeout, a `["PATH", "HOME"]` env allowlist, and a 1 MiB
121	    /// output cap.
122	    pub fn builder(sandbox: Sandbox) -> BashToolBuilder {
123	        BashToolBuilder {
124	            sandbox,
125	            timeout: DEFAULT_TIMEOUT,
126	            env_allowlist: vec!["PATH".to_owned(), "HOME".to_owned()],
127	            max_output_bytes: DEFAULT_MAX_OUTPUT,
128	            deny_commands: Vec::new(),
129	            allow_commands: None,
130	        }
131	    }
132	}
133	
134	impl<Ctx> BashTool<Ctx> {
135	    fn check_command_allowed(&self, command: &str) -> Result<(), ToolError> {
136	        let first = command.split_whitespace().next().unwrap_or("");
137	        if self.deny_commands.iter().any(|d| d == first) {
138	            return Err(ToolError::Denied {
139	                reason: format!("command `{first}` is blocked by the deny list"),
140	            });
141	        }
142	        if let Some(allow) = &self.allow_commands {
143	            if !allow.iter().any(|a| a == first) {
144	                return Err(ToolError::Denied {
145	                    reason: format!("command `{first}` is not in the allow list"),
146	                });
147	            }
148	        }
149	        Ok(())
150	    }
151	}
152	
153	#[async_trait]
154	impl<Ctx> Tool<Ctx> for BashTool<Ctx>
155	where
156	    Ctx: Send + Sync + 'static,
157	{
158	    fn name(&self) -> &str {
159	        "Bash"
160	    }
161	
162	    fn description(&self) -> &str {
163	        "Run a shell command with the working directory pinned to the sandbox \
164	         root. WARNING: this is NOT a security sandbox — the command can read/ \
165	         write anything this process can (absolute paths, the network). It is \
166	         ungated unless a PermissionPolicy or a DenyRule for `Bash` is installed."
167	    }
168	
169	    fn schema(&self) -> &Value {
170	        &self.schema
171	    }
172	
173	    fn effect(&self) -> ToolEffect {
174	        ToolEffect::SideEffect
175	    }
176	
177	    async fn invoke(&self, _ctx: &ToolContext<Ctx>, args: Value) -> Result<ToolOutput, ToolError> {
178	        let args: BashArgs = serde_json::from_value(args).map_err(|e| ToolError::InvalidArgs {
179	            schema_errors: vec![e.to_string()],
180	        })?;
181	        self.check_command_allowed(&args.command)?;
182	
183	        let mut cmd = build_command(&args.command);
184	        cmd.current_dir(self.sandbox.root())
185	            .env_clear()
186	            .stdin(Stdio::null())
187	            .stdout(Stdio::piped())
188	            .stderr(Stdio::piped());
189	        for name in &self.env_allowlist {
190	            if let Ok(val) = std::env::var(name) {
191	                cmd.env(name, val);
192	            }
193	        }
194	        #[cfg(unix)]
195	        {
196	            // New process group so a timeout can kill the whole group.
197	            cmd.process_group(0);
198	        }
199	
200	        let mut child = cmd
201	            .spawn()
202	            .map_err(|e| ToolError::Other(anyhow::anyhow!("failed to spawn shell: {e}")))?;
203	
204	        // Capture the pid (== the process-group id, because `process_group(0)`
205	        // above made the child its own group leader) BEFORE reaping it, so a
206	        // timeout kill can target the whole group with no PID-reuse race.
207	        #[cfg(unix)]
208	        let pgid = child.id();
209	
210	        let stdout_pipe = child.stdout.take().expect("piped stdout");
211	        let stderr_pipe = child.stderr.take().expect("piped stderr");
212	
213	        let cap = self.max_output_bytes;
214	        // Drain both pipes concurrently with the wait so a child cannot block
215	        // on a full pipe buffer (classic deadlock).
216	        let out_handle = tokio::spawn(read_capped(stdout_pipe, cap));
217	        let err_handle = tokio::spawn(read_capped(stderr_pipe, cap));
218	
219	        let mut timed_out = false;
220	        let exit_code: Option<i32>;
221	        match tokio::time::timeout(self.timeout, child.wait()).await {
222	            Ok(status) => {
223	                exit_code = status.map_err(|e| ToolError::Other(e.into()))?.code();
224	            }
225	            Err(_) => {
226	                timed_out = true;
227	                // Kill the WHOLE process group (unix) so backgrounded
228	                // grandchildren die too and release the stdout/stderr pipes.
229	                // The child is not yet reaped, so `pgid` is still valid.
230	                #[cfg(unix)]
231	                {
232	                    if let Some(pid) = pgid {
233	                        // pid < 4_194_304 on all supported platforms, so the
234	                        // `as i32` cast and negation are safe. A kill error
235	                        // here (e.g. ESRCH if the group already exited) is
236	                        // benign — the bounded wait/drain below still returns.
237	                        let _ = unsafe { libc::kill(-(pid as i32), libc::SIGKILL) };
238	                    }
239	                }
240	                #[cfg(not(unix))]
241	                {
242	                    // No portable group kill; best-effort direct-child kill.
243	                    let _ = child.start_kill();
244	                }
245	                // Bounded reap so an uninterruptible (D-state) process can't
246	                // hang the invocation.
247	                exit_code = match tokio::time::timeout(GRACE, child.wait()).await {
248	                    Ok(Ok(status)) => status.code(),
249	                    _ => None,
250	                };
251	            }
252	        }
253	
254	        // Join the reader tasks, BOUNDED: on the success path a leaked
255	        // backgrounded process (`cmd &`) can hold the pipe open, so we give the
256	        // readers a grace period then abort and return what we captured. This
257	        // guarantees `invoke` always returns.
258	        let ((stdout, out_trunc), (stderr, err_trunc)) =
259	            tokio::join!(join_reader(out_handle), join_reader(err_handle));
260	
261	        Ok(ToolOutput::new(serde_json::json!({
262	            "stdout": stdout,
263	            "stderr": stderr,
264	            "exit_code": exit_code,
265	            "timed_out": timed_out,
266	            "truncated": out_trunc || err_trunc,
267	        })))
268	    }
269	}
270	
271	/// Build the platform shell command without yet setting cwd/env.
272	fn build_command(command: &str) -> tokio::process::Command {
273	    #[cfg(unix)]
274	    {
275	        let mut c = tokio::process::Command::new("sh");
276	        c.arg("-c").arg(command);
277	        c
278	    }
279	    #[cfg(windows)]
280	    {
281	        let mut c = tokio::process::Command::new("cmd");
282	        c.arg("/C").arg(command);
283	        c
284	    }
285	}
286	
287	/// Await a spawned reader task, bounded by [`GRACE`]. If it does not finish in
288	/// time (e.g. a leaked background process is holding the pipe open), abort it
289	/// and return empty output rather than hanging the invocation.
290	async fn join_reader(handle: tokio::task::JoinHandle<(String, bool)>) -> (String, bool) {
291	    let abort = handle.abort_handle();
292	    match tokio::time::timeout(GRACE, handle).await {
293	        Ok(Ok(captured)) => captured,
294	        _ => {
295	            abort.abort();
296	            (String::new(), false)
297	        }
298	    }
299	}
300	
301	/// Read up to `cap` bytes from `pipe` as lossy UTF-8; the bool is `true` if the
302	/// output was truncated at the cap. Takes the pipe by value so the spawned
303	/// reader task owns it and dropping it closes the underlying fd. I/O errors are
304	/// ignored — whatever was buffered up to that point is returned.
305	async fn read_capped<R>(pipe: R, cap: usize) -> (String, bool)
306	where
307	    R: tokio::io::AsyncRead + Unpin + Send + 'static,
308	{
309	    let mut buf = Vec::new();
310	    // Read a little past the cap so we can detect truncation, then trim.
311	    let _ = pipe.take((cap as u64) + 1).read_to_end(&mut buf).await;
312	    let truncated = buf.len() > cap;
313	    buf.truncate(cap);
314	    (String::from_utf8_lossy(&buf).into_owned(), truncated)
315	}
