216	#[cfg(test)]
217	mod tests {
218	    use super::*;
219	    use std::net::{IpAddr, Ipv4Addr};
220	
221	    fn ip(s: &str) -> IpAddr {
222	        s.parse().unwrap()
223	    }
224	
225	    #[test]
226	    fn ip_blocked_rejects_private_and_special_ranges() {
227	        for s in [
228	            "127.0.0.1",       // loopback
229	            "10.0.0.1",        // RFC1918
230	            "172.16.0.1",      // RFC1918
231	            "192.168.1.1",     // RFC1918
232	            "169.254.169.254", // link-local / cloud metadata
233	            "100.64.0.1",      // CGNAT
234	            "0.0.0.0",         // unspecified
235	            "198.18.0.1",      // benchmarking 198.18.0.0/15
236	            "198.19.0.1",      // benchmarking 198.18.0.0/15
237	            "240.0.0.1",       // reserved-for-future 240.0.0.0/4
238	            "::1",             // v6 loopback
239	            "fc00::1",         // v6 ULA
240	            "fe80::1",         // v6 link-local
241	            "ff02::1",         // v6 multicast
242	            "2001:db8::1",     // v6 documentation 2001:db8::/32
243	        ] {
244	            assert!(ip_blocked(ip(s)), "{s} should be blocked");
245	        }
246	    }
247	
248	    #[test]
249	    fn ip_blocked_allows_public_addresses() {
250	        for s in ["8.8.8.8", "1.1.1.1", "2606:4700:4700::1111"] {
251	            assert!(!ip_blocked(ip(s)), "{s} should be allowed");
252	        }
253	    }
254	
255	    #[test]
