1	//! The capability-confined [`Sandbox`] shared by the filesystem tools.
2	
3	use std::path::{Component, Path, PathBuf};
4	use std::sync::Arc;
5	
6	use cap_std::ambient_authority;
7	use cap_std::fs::Dir;
8	
9	/// A directory opened as an OS-confined capability. Filesystem operations
10	/// performed through this handle are resolved relative to the root and cannot
11	/// escape it (`..`, absolute paths, and escaping symlinks are rejected).
12	///
13	/// Cheap to clone (it is `Arc`-backed); share one `Sandbox` across many tools.
14	#[derive(Clone, Debug)]
15	pub struct Sandbox {
16	    inner: Arc<SandboxInner>,
17	}
18	
19	#[derive(Debug)]
20	struct SandboxInner {
21	    root: PathBuf,
22	    dir: Dir,
23	}
24	
25	impl Sandbox {
26	    /// Open `root` as a capability-confined sandbox.
27	    pub fn open(root: impl AsRef<Path>) -> Result<Self, SandboxError> {
28	        let root = root.as_ref();
29	        let dir = Dir::open_ambient_dir(root, ambient_authority()).map_err(|source| {
30	            SandboxError::Open {
31	                path: root.to_path_buf(),
32	                source,
33	            }
34	        })?;
35	        let canonical = root.canonicalize().map_err(|source| SandboxError::Open {
36	            path: root.to_path_buf(),
37	            source,
38	        })?;
39	        Ok(Self {
40	            inner: Arc::new(SandboxInner {
41	                root: canonical,
42	                dir,
43	            }),
44	        })
45	    }
46	
47	    /// The canonical sandbox root on the host filesystem (diagnostics / cwd).
48	    pub fn root(&self) -> &Path {
49	        &self.inner.root
50	    }
51	
52	    /// The underlying capability directory handle.
53	    pub(crate) fn dir(&self) -> &Dir {
54	        &self.inner.dir
55	    }
56	}
57	
58	/// Reject a tool-supplied path that is absolute or contains a `..`/root/prefix
59	/// component before it reaches the capability layer. The `cap-std` `Dir` is the
60	/// backstop for symlink escapes; this is the deterministic front gate.
61	pub(crate) fn guard_relative(path: &str) -> Result<&Path, String> {
62	    let p = Path::new(path);
63	    if p.components().any(|c| {
64	        matches!(
65	            c,
66	            Component::ParentDir | Component::RootDir | Component::Prefix(_)
67	        )
68	    }) {
69	        return Err(format!("path escapes the sandbox root: {path}"));
70	    }
71	    Ok(p)
72	}
73	
74	/// Errors from constructing a [`Sandbox`]. In-`invoke` boundary violations use
75	/// [`paigasus_helikon_core::ToolError::Denied`], not this type.
76	#[derive(Debug, thiserror::Error)]
77	#[non_exhaustive]
78	pub enum SandboxError {
79	    /// The sandbox root could not be opened (missing, not a directory, perms).
80	    #[error("cannot open sandbox root {path}: {source}")]
81	    Open {
82	        /// The path that failed to open.
83	        path: PathBuf,
84	        /// The underlying I/O error.
85	        source: std::io::Error,
86	    },
87	}
88	
89	#[cfg(test)]
90	mod tests {
91	    use super::guard_relative;
92	    use std::path::Path;
93	
94	    #[test]
95	    fn rejects_parent_dir() {
96	        assert!(guard_relative("../escape").is_err());
97	        assert!(guard_relative("a/../b").is_err());
98	    }
99	
100	    #[test]
101	    fn rejects_absolute() {
102	        assert!(guard_relative("/etc/passwd").is_err());
103	    }
104	
105	    #[test]
106	    fn accepts_nested_relative() {
107	        assert_eq!(guard_relative("a/b/c.txt").unwrap(), Path::new("a/b/c.txt"));
108	    }
109	
110	    #[test]
111	    fn accepts_dotdot_prefix_filename() {
112	        // "..foo" is a single Normal component, not a ParentDir component.
113	        assert!(guard_relative("..foo").is_ok());
114	    }
115	
116	    #[test]
117	    fn accepts_cur_dir_prefix() {
118	        // "./a" has a CurDir component, which the guard intentionally allows.
119	        assert!(guard_relative("./a").is_ok());
120	    }
121	}
